class Solution {
    public int minOperations(java.util.List<Integer> nums, int k) {
        java.util.Set<Integer> needed = new java.util.HashSet<>();
        for (int value = 1; value <= k; value++) {
            needed.add(value);
        }
        int operations = 0;
        for (int index = nums.size() - 1; index >= 0; index--) {
            operations++;
            needed.remove(nums.get(index));
            if (needed.isEmpty()) {
                return operations;
            }
        }
        return operations;
    }
}

class Solution {
    public int minOperations(java.util.List<Integer> nums, int k) {
        boolean[] seen = new boolean[k + 1];
        int remaining = k;
        int operations = 0;
        for (int index = nums.size() - 1; index >= 0; index--) {
            operations++;
            int value = nums.get(index);
            if (value <= k && !seen[value]) {
                seen[value] = true;
                remaining--;
                if (remaining == 0) {
                    return operations;
                }
            }
        }
        return operations;
    }
}

class Solution {
    public int minOperations(java.util.List<Integer> nums, int k) {
        java.util.BitSet collected = new java.util.BitSet(k + 1);
        int operations = 0;
        for (int index = nums.size() - 1; index >= 0; index--) {
            operations++;
            int value = nums.get(index);
            if (1 <= value && value <= k) {
                collected.set(value);
                if (collected.cardinality() == k) {
                    return operations;
                }
            }
        }
        return operations;
    }
}

class Solution {
    public int minOperations(java.util.List<Integer> nums, int k) {
        boolean[] seen = new boolean[k + 1];
        int collected = 0;
        int start = nums.size();
        for (int index = nums.size() - 1; index >= 0; index--) {
            int value = nums.get(index);
            if (value <= k && !seen[value]) {
                seen[value] = true;
                collected++;
                start = index;
                if (collected == k) {
                    break;
                }
            }
        }
        return nums.size() - start;
    }
}
